def _finite(x):
    return isinstance(x, float) and math.isfinite(x)


def secant(f, s0, s1, tol=1e-12, max_iter=100):
    """Bracket-safe secant method.

    Standard secant updates, but whenever an iterate would leave the
    initial interval [min(s0, s1), max(s0, s1)] it is replaced by its
    midpoint (bisection fallback).  This prevents the iteration from
    jumping to roots *outside* the starting bracket -- important here
    because this BVP has a second, spurious solution branch with slope
    s ~= -35.86.  Non-convergence is reported through a status flag,
    never by raising an exception (also covers NaN/inf from wild starts).
    """
    fs0, fs1 = f(s0), f(s1)
    lo, hi = (s0, s1) if s0 <= s1 else (s1, s0)
    for it in range(1, max_iter + 1):
        if not (_finite(fs0) and _finite(fs1)):
            return SecantResult(None, it, False, None)
        if fs1 == fs0:                      # degenerate denominator
            return SecantResult(None, it, False, None)
        s2 = s1 - fs1 * (s1 - s0) / (fs1 - fs0)
        if not (lo <= s2 <= hi):            # left the bracket -> bisect
            s2 = 0.5 * (lo + hi)
        fs2 = f(s2)
        if not _finite(fs2):
            return SecantResult(None, it, False, None)
        s0, fs0, s1, fs1 = s1, fs1, s2, fs2
        if abs(fs1) < tol:
            return SecantResult(s1, it, True, abs(fs1))
        # shrink the bracket when the new point straddles a sign change
        if fs1 * fs0 < 0:
            lo, hi = (s0, s1) if s0 < s1 else (s1, s0)
        elif fs1 * fs2 < 0:
            lo, hi = (s1, s2) if s1 < s2 else (s2, s1)
    return SecantResult(None, max_iter, False, abs(fs1))"}, {"old": """"

